1	package nexusbench
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"reflect"
9		"regexp"
10		"strings"
11		"testing"
12	)
13	
14	// The tests of the schema 2 descriptor (DEVDESK-505, NX-02a, step 8; Plane
15	// DEVDESK-543). Decision D-M of the plan:
16	//
17	//	BuildDescriptor(p Params, d DeployResult, r ProvisionResult, s SeedResult) Descriptor
18	//
19	//   - schemaVersion is 2 and LoadDescriptor accepts nothing else: a schema 1 file
20	//     is a *BenchError whose Check says to run `mise run nexus-bench:up`;
21	//   - three sections follow "accounts", in this order: registryAccess (scheme
22	//     "http", tlsVerify false, routing "path"), upstream (service, image, url,
23	//     persistent true, exposure "port-forward") and dataset (one entry per image
24	//     of the SeedResult, in its order: name, tag, digest, location, cachedInProxy);
25	//   - cachedInProxy is DatasetImage.PullThrough: a seeded image is cached in
26	//     docker-proxy exactly when Seed pulled it through;
27	//   - the dataset comes from the SeedResult, not from Dataset(): an empty result
28	//     lists no image, and the section is then "[]", never null;
29	//   - ProxyPending false (the nominal case of NX-02) lists docker-proxy and makes
30	//     it a member of docker-group;
31	//   - no secret, no timestamp, no credential in a URL.
32	//
33	// The golden testdata/descriptor.example.json is v1 until the code lands: the
34	// golden tests of descriptor_test.go are red for that reason, and the coder
35	// regenerates it with `-run TestDescriptorGolden -update` and reviews the diff.
36	
37	// descriptorV1 is what a bench of NX-01 wrote: the committed descriptor.json
38	// before NX-02.
39	const descriptorV1 = `{
40	  "schemaVersion": 1,
41	  "kubeContext": "datomir",
42	  "namespace": "nexus-bench",
43	  "image": "docker.io/sonatype/nexus3:3.98.1",
44	  "nexusVersion": "3.98.1-01",
45	  "edition": "COMMUNITY",
46	  "eulaAccepted": true,
47	  "hosts": ["127.0.0.1"],
48	  "rest": {"nodePort": 30481, "containerPort": 8081, "urls": ["http://127.0.0.1:30481"]},
49	  "dockerConnectors": [],
50	  "repositories": [{"name": "docker-hosted", "type": "hosted"}],
51	  "realms": ["NexusAuthenticatingRealm"],
52	  "accounts": []
53	}
54	`
55	
56	// rawKeys returns the keys of a JSON object, in file order.
57	func rawKeys(t *testing.T, raw json.RawMessage) []string {
58		t.Helper()
59		return topLevelKeys(t, raw)
60	}
61	
62	func writtenDescriptor(t *testing.T, d Descriptor) []byte {
63		t.Helper()
64		path := filepath.Join(t.TempDir(), "descriptor.json")
65		if err := WriteDescriptor(path, d); err != nil {
66			t.Fatalf("WriteDescriptor: %v", err)
67		}
68		data, err := os.ReadFile(path)
69		if err != nil {
70			t.Fatal(err)
71		}
72		return data
73	}
74	
75	func TestDescriptorV2SectionsAndFieldOrder(t *testing.T) {
76		data := writtenDescriptor(t, sampleDescriptor())
77		var top map[string]json.RawMessage
78		if err := json.Unmarshal(data, &top); err != nil {
79			t.Fatal(err)
80		}
81	
82		for _, tt := range []struct {
83			section string
84			want    []string
85		}{
86			{"registryAccess", []string{"scheme", "tlsVerify", "routing"}},
87			{"upstream", []string{"service", "image", "url", "persistent", "exposure"}},
88		} {
89			raw, ok := top[tt.section]
90			if !ok {
91				t.Errorf("the descriptor has no %q section", tt.section)
92				continue
93			}
94			if got := rawKeys(t, raw); !reflect.DeepEqual(got, tt.want) {
95				t.Errorf("%s keys = %v, want %v", tt.section, got, tt.want)
96			}
97		}
98	
99		var entries []json.RawMessage
100		if err := json.Unmarshal(top["dataset"], &entries); err != nil || len(entries) == 0 {
101			t.Fatalf("dataset = %s, want a list of images (%v)", top["dataset"], err)
102		}
103		for i, e := range entries {
104			if got, want := rawKeys(t, e), []string{"name", "tag", "digest", "location", "cachedInProxy"}; !reflect.DeepEqual(got, want) {
105				t.Errorf("dataset[%d] keys = %v, want %v", i, got, want)
106			}
107		}
108	
109		// A false and a true that are written, not left out.
110		text := string(data)
111		for _, want := range []string{`"scheme": "http"`, `"tlsVerify": false`, `"routing": "path"`, `"persistent": true`, `"exposure": "port-forward"`, `"service": "bench-upstream"`} {
112			if !strings.Contains(text, want) {
113				t.Errorf("the descriptor lacks %s:\n%s", want, text)
114			}
115		}
116	}
