118	func TestBuildDescriptorDatasetFollowsTheSeedResult(t *testing.T) {
119		t.Run("the whole data set, in order, with the cache state", func(t *testing.T) {
120			d := sampleDescriptor()
121			if want := wantDescriptorDataset(Dataset()); !reflect.DeepEqual(d.Dataset, want) {
122				t.Fatalf("dataset =\n%+v\nwant\n%+v", d.Dataset, want)
123			}
124			cached := 0
125			for _, img := range d.Dataset {
126				if img.CachedInProxy {
127					cached++
128					if img.Name != "mirror/cached" {
129						t.Errorf("%s:%s is marked cached in the proxy", img.Name, img.Tag)
130					}
131				}
132				if !regexp.MustCompile(`^sha256:[0-9a-f]{64}$`).MatchString(img.Digest) {
133					t.Errorf("%s:%s digest = %q, want sha256:<64 hex>", img.Name, img.Tag, img.Digest)
134				}
135			}
136			if cached != 1 {
137				t.Errorf("%d images are cached in the proxy, want 1", cached)
138			}
139		})
140	
141		t.Run("what the seed result says, not Dataset()", func(t *testing.T) {
142			images := []DatasetImage{
143				{Name: "z/last", Tag: "9", Location: LocationUpstream, PullThrough: true, Digest: digestAlpine},
144				{Name: "a/first", Tag: "1", Location: LocationHosted, Digest: digestBusy},
145			}
146			d := BuildDescriptor(Defaults(), sampleDeploy(), sampleProvision(), SeedResult{Images: images})
147			want := []DescriptorImage{
148				{Name: "z/last", Tag: "9", Digest: digestAlpine, Location: "upstream", CachedInProxy: true},
149				{Name: "a/first", Tag: "1", Digest: digestBusy, Location: "docker-hosted", CachedInProxy: false},
150			}
151			if !reflect.DeepEqual(d.Dataset, want) {
152				t.Errorf("dataset = %+v, want %+v", d.Dataset, want)
153			}
154		})
155	
156		t.Run("an empty result lists no image, and writes [] not null", func(t *testing.T) {
157			d := BuildDescriptor(Defaults(), sampleDeploy(), sampleProvision(), SeedResult{})
158			if d.Dataset == nil || len(d.Dataset) != 0 {
159				t.Errorf("dataset = %#v, want an empty, non-nil list", d.Dataset)
160			}
161			if text := string(writtenDescriptor(t, d)); !strings.Contains(text, `"dataset": []`) {
162				t.Errorf("the empty dataset is not written as []:\n%s", text)
163			}
164		})
165	
166		t.Run("the descriptor does not share the slice of the result", func(t *testing.T) {
167			s := sampleSeed()
168			d := BuildDescriptor(Defaults(), sampleDeploy(), sampleProvision(), s)
169			if len(d.Dataset) == 0 {
170				t.Fatal("the descriptor lists no image")
171			}
172			first := d.Dataset[0]
173			s.Images[0].Name = "changed"
174			s.Images[0].PullThrough = !s.Images[0].PullThrough
175			if d.Dataset[0] != first {
176				t.Errorf("dataset[0] = %+v follows the result, was %+v", d.Dataset[0], first)
177			}
178		})
179	}
