181	func TestBuildDescriptorListsTheProxyOnceTheUpstreamResolves(t *testing.T) {
182		r := sampleProvision()
183		r.ProxyPending = false
184		d := BuildDescriptor(Defaults(), sampleDeploy(), r, sampleSeed())
185		want := []DescriptorRepository{
186			{Name: "docker-hosted", Type: "hosted"},
187			{Name: "docker-proxy", Type: "proxy", RemoteURL: "http://bench-upstream.nexus-bench.svc.cluster.local:5000"},
188			{Name: "docker-group", Type: "group", Members: []string{"docker-hosted", "docker-proxy"}},
189		}
190		if !reflect.DeepEqual(d.Repositories, want) {
191			t.Errorf("repositories = %+v, want %+v", d.Repositories, want)
192		}
193	}
