195	func TestBuildDescriptorUpstreamFollowsTheImageParameters(t *testing.T) {
196		tests := []struct {
197			name      string
198			image     string
199			tag       string
200			wantImage string
201		}{
202			{"defaults", "docker.io/library/registry", "3.0.0", "docker.io/library/registry:3.0.0"},
203			{"another tag", "docker.io/library/registry", "3.0.1", "docker.io/library/registry:3.0.1"},
204			{"another image", "registry.example/mirror/registry", "2.8.3", "registry.example/mirror/registry:2.8.3"},
205		}
206		for _, tt := range tests {
207			t.Run(tt.name, func(t *testing.T) {
208				p := Defaults()
209				p.UpstreamImage, p.UpstreamImageTag = tt.image, tt.tag
210				d := BuildDescriptor(p, sampleDeploy(), sampleProvision(), sampleSeed())
211				if d.Upstream.Image != tt.wantImage || d.Upstream.Image != p.UpstreamImageRef() {
212					t.Errorf("upstream image = %q, want %q", d.Upstream.Image, tt.wantImage)
213				}
214				if d.Upstream.Service != "bench-upstream" || !d.Upstream.Persistent || d.Upstream.Exposure != "port-forward" {
215					t.Errorf("upstream = %+v, want service bench-upstream, persistent, port-forward", d.Upstream)
216				}
217				if d.Upstream.URL != p.UpstreamURL {
218					t.Errorf("upstream url = %q, want %q", d.Upstream.URL, p.UpstreamURL)
219				}
220				if want := (RegistryAccess{Scheme: "http", TLSVerify: false, Routing: "path"}); d.RegistryAccess != want {
221					t.Errorf("registryAccess = %+v, want %+v", d.RegistryAccess, want)
222				}
223			})
224		}
225	}
