227	func TestLoadDescriptorRefusesSchemaVersion1(t *testing.T) {
228		good := string(mustMarshalIndent(t, sampleDescriptor()))
229		tests := []struct {
230			name    string
231			content string
232		}{
233			{"a file written by NX-01", descriptorV1},
234			{"a v2 body marked as v1", strings.Replace(good, `"schemaVersion": 2`, `"schemaVersion": 1`, 1)},
235		}
236		for _, tt := range tests {
237			t.Run(tt.name, func(t *testing.T) {
238				path := filepath.Join(t.TempDir(), "descriptor.json")
239				if err := os.WriteFile(path, []byte(tt.content), 0o644); err != nil {
240					t.Fatal(err)
241				}
242				_, err := LoadDescriptor(path)
243				if err == nil {
244					t.Fatal("LoadDescriptor accepted a schema 1 file")
245				}
246				if errors.Is(err, ErrNoDescriptor) {
247					t.Errorf("a schema 1 file is not an absent one: %v", err)
248				}
249				var be *BenchError
250				if !errors.As(err, &be) {
251					t.Fatalf("error = %#v, want a *BenchError", err)
252				}
253				if !strings.Contains(be.Check, "nexus-bench:up") {
254					t.Errorf("Check = %q, want it to say to run mise run nexus-bench:up", be.Check)
255				}
256				if !strings.Contains(strings.ToLower(err.Error()), "schema") {
257					t.Errorf("error %q does not mention the schema", err)
258				}
259			})
260		}
261	}
262	
263	func TestDescriptorV2HoldsNoSecretNoDateNoCredential(t *testing.T) {
264		text := string(writtenDescriptor(t, sampleDescriptor()))
265		lower := strings.ToLower(text)
266		for _, banned := range []string{"password", "secret", "authfile", "credential", strings.ToLower(secretMarker)} {
267			if strings.Contains(lower, banned) {
268				t.Errorf("the descriptor mentions %q:\n%s", banned, text)
269			}
270		}
271		for label, re := range map[string]*regexp.Regexp{
272			"a date":                  regexp.MustCompile(`\d{4}-\d{2}-\d{2}`),
273			"a time":                  regexp.MustCompile(`\d{2}:\d{2}:\d{2}`),
274			"credentials in a URL":    regexp.MustCompile(`://[^/"\s]*@`),
275			"a temporary folder path": regexp.MustCompile(`devdesk-(skopeo|seed)-|/tmp/`),
276		} {
277			if m := re.FindString(text); m != "" {
278				t.Errorf("the descriptor holds %s (%q)", label, m)
279			}
280		}
281	}
